await page.goto('/ops/radar');
await expect(page).toHaveURL(/\/ops\/radar/);

// Radar clock: a visible time-like text (e.g. 14:05 or 14:05:09)
const clock = page.getByText(/\b\d{1,2}:\d{2}(:\d{2})?\b/).first();
await expect(clock).toBeVisible();
await expect(clock).not.toHaveCSS('font-size', '8px');

// Row title: title element inside the first radar row
const rowTitle = page.getByRole('row').locator('[class*="title" i]').first();
await expect(rowTitle).toBeVisible();
await expect(rowTitle).not.toHaveCSS('font-size', '8px');
